DELETE FROM config_baselines WHERE id IN (
    '30000000-0008-4000-8000-000000000001',
    '30000000-0008-4000-8000-000000000002',
    '30000000-0008-4000-8000-000000000003',
    '30000000-0008-4000-8000-000000000004'
);

